const index = global.get('aboxIndex') || null;
if (!index) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'aboxIndex missing' });
    const obs = (msg.payload && msg.payload.observations) || [];
    const unmapped = obs.map((o) => ({
        source: msg.payload && msg.payload.source,
        device_id: msg.payload && msg.payload.device_id,
        field: o && o.field,
        value: o && o.value,
        reason: 'abox_not_loaded'
    }));
    return [null, unmapped.map((u) => ({ payload: u, topic: 'unmapped' }))];
}

const p = msg.payload || {};
const src = p.source;
const devId = p.device_id;
const ts = p.ts ? new Date(p.ts).toISOString() : new Date().toISOString();
const observations = Array.isArray(p.observations) ? p.observations : [];
const homeId = p.home_id || global.get('homeId') || 'unknown';

const CONTEXT = 'https://schema.digitalhome.cloud/cbox/v0/context.jsonld';

const coerce = (raw, kind) => {
    switch (kind) {
        case 'byte-to-percent':
            return typeof raw === 'number' ? Math.round(raw * 10000 / 254) / 100 : raw;
        case 'unit-to-percent':
            return typeof raw === 'number' ? Math.round(raw * 10000) / 100 : raw;
        case 'mired-to-kelvin':
            return typeof raw === 'number' && raw > 0 ? Math.round(1000000 / raw) : raw;
        case 'centi-to-unit':
            return typeof raw === 'number' ? raw / 100 : raw;
        case 'hue-lightlevel-to-lux':
            return typeof raw === 'number' ? Math.round(Math.pow(10, (raw - 1) / 10000) * 100) / 100 : raw;
        case 'wh-to-kwh':
            return typeof raw === 'number' ? raw / 1000 : raw;
        case 'invert-boolean':
            return typeof raw === 'boolean' ? !raw : (raw ? false : true);
        default:
            return raw;
    }
};

const uuidV4 = () => {
    const b = new Uint8Array(16);
    for (let i = 0; i < 16; i++) b[i] = Math.floor(Math.random() * 256);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    const h = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
    return h.slice(0, 8) + '-' + h.slice(8, 12) + '-' + h.slice(12, 16) + '-' + h.slice(16, 20) + '-' + h.slice(20);
};

const mapped = [];
const unmapped = [];

for (const obs of observations) {
    if (!obs || obs.field == null) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs && obs.field, value: obs && obs.value, reason: 'malformed_observation' });
        continue;
    }
    const key = src + '/' + obs.field;
    const entry = index.sourceMap[key];
    if (!entry) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs.field, value: obs.value, reason: 'unknown_source_field' });
        continue;
    }
    const capMeta = index.capability[entry.capability];
    if (!capMeta) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs.field, value: obs.value, reason: 'missing_capability', capability: entry.capability });
        continue;
    }
    const value = entry.coerce ? coerce(obs.value, entry.coerce) : obs.value;
    const fragment = {
        '@context': CONTEXT,
        '@id': 'urn:dhe:point:' + uuidV4(),
        '@type': capMeta.brickClass,
        'dhc:capability': entry.capability,
        'dhc:value': value,
        'dhc:observedAt': ts,
        'dhc:source': 'urn:dhe:' + src,
        'dhc:pointOf': 'urn:dhe:device:' + src + ':' + devId,
        'dhc:homeId': homeId
    };
    if (capMeta.unit)      fragment['dhc:unit']      = capMeta.unit;
    if (capMeta.valueType) fragment['dhc:valueType'] = capMeta.valueType;
    mapped.push(fragment);
}

const counts = flow.get('aboxFilterCounts') || { mapped: 0, unmapped: 0 };
counts.mapped   += mapped.length;
counts.unmapped += unmapped.length;
flow.set('aboxFilterCounts', counts);
node.status({ fill: 'green', shape: 'dot', text: 'mapped ' + counts.mapped + ' / unmapped ' + counts.unmapped });

const outMapped = mapped.map((f) => ({ payload: f, topic: 'cbox' }));
const outUnmapped = unmapped.map((u) => ({ payload: u, topic: 'unmapped' }));

return [
    outMapped.length ? outMapped : null,
    outUnmapped.length ? outUnmapped : null
];
